    def test_failing_checks_render_first(self):
        # Visual verdict #147 follow-up (2026-11-22,
        # checker-improvement): on the live noprot page the donation
        # table sat 951px below the banner at desktop width (1,673px
        # at 360px), behind the passing Rounding card — the verdict
        # was a screen and a half above its evidence. Failing checks
        # render first, in both renderers; the canonical order
        # survives within each group (stable sort), the banner still
        # names the failures, and an ALL PASS run is unchanged.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build

        def card_titles(html):
            cards = html.split("<section class='check-card'>")[1:]
            return [c.split("</span> ", 1)[1].split("</h3>", 1)[0]
                    for c in cards]

        # One failure: the donation card jumps from 2nd to 1st.
        failed = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertEqual(
            card_titles(failed),
            ["Donation inflation", "Rounding directions",
             "Minimum viable deposit", "Preview consistency",
             "Fee conservation", "Share-price sanity"])
        # Two failures: both lead, in canonical order, then passes.
        two = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=10**15,
                          perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=10**15, fee=0)
        self.assertEqual(
            card_titles(two),
            ["Donation inflation", "Minimum viable deposit",
             "Rounding directions", "Preview consistency",
             "Fee conservation", "Share-price sanity"])
        # ALL PASS: order unchanged.
        passed = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertEqual(
            card_titles(passed),
            ["Rounding directions", "Donation inflation",
             "Minimum viable deposit", "Preview consistency",
             "Fee conservation", "Share-price sanity"])
        # Worker JS renderer: resultsHTML sorts the same way.
        js = build.checker_results_html_js()
        fn = js[js.index("function resultsHTML"):]
        self.assertIn(
            "const ordered=[...results].sort((a,b)=>(a.pass?1:0)-(b.pass?1:0));",
            fn)
        self.assertIn("for(const r of ordered){", fn)
        self.assertNotIn("for(const r of results){", fn)

    def test_verdict_strip_above_form(self):
        # Visual verdict #119 item 2 (2026-11-19): the result banner
        # sits below the form, so a visitor arriving on
        # /checker/?preset=noprot sees the form first and must scroll
        # to learn the verdict. A one-line strip above the form must
        # carry the same verdict and link down to the full results.
        # The Worker JS renderer carries the same strip; it is verified
        # by the verdict-strip node harness, not by this suite.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        failed = build.verdict_strip_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)))
        self.assertIn("SOME FAILED", failed)
        self.assertIn("Donation inflation", failed)
        self.assertIn("verdict-strip fail", failed)
        self.assertIn('href="#results"', failed)
        # Visual verdict #146 (2026-11-21): the verdict sat a screen
        # and a half above its evidence — the failing table is below
        # the form. The strip now carries the headline number itself,
        # in the exact words the share card (ogMeta) uses, so the two
        # agree: the worst measured victim loss and the donation that
        # caused it. A custom victim deposit re-words the sentence
        # around the deposit actually run.
        self.assertIn("1,000,000 USDC donation: a 100,000 USDC deposit "
                      "loses 0.909091 USDC", failed)
        custom = build.verdict_strip_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                    victim_deposit=1_000_000_000), vic=1_000_000_000)
        self.assertIn("1,000,000 USDC donation: a 1,000 USDC deposit "
                      "loses 0.999001 USDC", custom)
        # Visual verdict #124 (g) (2026-11-20): a bare "&darr;" at the
        # end read as expand / decoration / jump-to-the-failed-item.
        # The strip must say in words where it goes — the full results
        # below the form — and never end on the bare arrow again.
        # 2026-11-20: "below &darr;" rides in a nowrap span so the
        # arrow never orphans alone on a line at 360px (headless
        # render: the ALL PASS strip left a bare "↓" on line 3).
        # The wording is unchanged; only the markup wraps it.
        self.assertIn("see the full results", failed)
        self.assertIn('<span class="nowrap">below &darr;</span>', failed)
        self.assertNotIn("Donation inflation &darr;", failed)
        # Visual verdict #147 (2026-11-22): the whole strip used to be
        # one underlined link on the red background, so the verdict
        # itself read as a hyperlink. Only the jump phrase is a link
        # now — the verdict (and its number) precedes the anchor as
        # plain text.
        self.assertLess(failed.index("SOME FAILED"),
                        failed.index('href="#results"'))
        self.assertIn('<a href="#results">see the full results', failed)
        passed = build.verdict_strip_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)))
        self.assertIn("ALL PASS", passed)
        self.assertIn("verdict-strip pass", passed)
        self.assertNotIn("SOME FAILED", passed)
        self.assertIn("see the full results", passed)
        self.assertIn('<span class="nowrap">below &darr;</span>', passed)
        self.assertNotIn("checks passed &darr;", passed)
        # Visual verdict #147 (2026-11-22): same de-linking on the
        # passing strip — the verdict precedes the anchor as plain text.
        self.assertLess(passed.index("ALL PASS"),
                        passed.index('href="#results"'))
        self.assertIn('<a href="#results">see the full results', passed)
        # An ALL PASS strip carries no loss number: the donation check
        # passed, so quoting its (nonzero but within-bound) worst loss
        # next to a pass would read as a failure.
        self.assertNotIn("loses", passed)

