    def test_footer_contrast_on_sage(self):
        # Visual verdict #142 item 13 (2026-11-21): the footer sits
        # outside <main>, directly on the sage body background
        # #c9d1c9 — the old #6b7280 footer text was ~3.1:1, below
        # WCAG AA 4.5:1 for normal text. Both the footer text and
        # its links must clear 4.5:1 against the sage, computed
        # from the colours actually in build.CSS (not hardcoded
        # here), so a future grey swap that breaks AA fails loudly.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build

        def lum(hexs):
            rgb = [int(hexs[i:i + 2], 16) / 255 for i in (0, 2, 4)]
            lin = [c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
                   for c in rgb]
            return 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2]

        bg = re.search(r"body\{[^}]*background:(#[0-9a-f]{6})", build.CSS).group(1)
        self.assertEqual(bg, "#c9d1c9")
        for rule in (r"footer\{[^}]*color:(#[0-9a-f]{6})",
                     r"footer a\{[^}]*color:(#[0-9a-f]{6})"):
            fg = re.search(rule, build.CSS).group(1)
            ratio = (lum(bg[1:]) + 0.05) / (lum(fg[1:]) + 0.05)
            self.assertGreaterEqual(ratio, 4.5, f"{rule} {fg} vs {bg}: {ratio:.2f}:1")

    def test_run_checks_button_is_sticky(self):
        # Headless measurement (2026-11-20, checker-improvement):
        # at 1919x998 the submit button's natural top is 1124px
        # (126px below the fold) and at 360x800 it is 1315px — the
        # form's only action is invisible on first paint on every
        # viewport, even after the #109 mobile compaction. The button
        # now rides in a sticky bar at the form's bottom edge,
        # settling into its natural place once the form is fully
        # scrolled into view. The bar bleeds to the card edges
        # and carries the card's own background, so it reads as the
        # card's foot, not a floating button.
        # 2026-11-20 fix (verdict #128 item 1): the bar was
        # position:sticky;bottom:0, which pulled it UP into the
        # viewport the moment its natural spot fell below the fold
        # -- at 1919x998 load it covered 36 of the 45px of the
        # last-row inputs and the form looked broken. It is now
        # top:calc(100vh - 89px): it sticks only once scrolling
        # brings its top to the viewport-bottom line, so at load it
        # stays in flow below the fold and covers nothing. 89px is
        # the measured desktop bar height; mobile is 84px, set by
        # the <=640px media query (see
        # test_run_bar_mobile_top_offset).
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
