        import build
        home = dict((p, b) for p, t, d, k, b in build.PAGES)["/"]
        self.assertIn(
            ".hero-top{display:flex;gap:2em;align-items:stretch}",
            build.CSS)
        self.assertIn(
            ".hero-top>div{flex:1;min-width:0;display:flex;"
            "flex-direction:column;justify-content:space-between}",
            build.CSS)
