    def test_hero_flow_step_bodies_are_single_line(self):
        # Visual verdict #57: step 3's body wrapped to two lines
        # ("0.909091 USDC of a 100,000 USDC deposit") while steps 1-2
        # were one line, so the equal-height cards left ~35px of dead
        # white space at the bottom of steps 1-2. The full sentence
        # already sits in the paragraph directly above the flow and in
        # the flow's aria-label, so the step body is just the figure.
        # Visual verdict #111 changed the shape: each step now carries
        # one extra sub-line (.flow-note, a separate block line) because
        # the bare figures left the cards looking like unfilled
        # placeholders. The #57 rule survives per line: the value line
        # and the note line must each fit on one line at the desktop
        # card width (~366px inner; the note runs at .88em, so 40 chars
        # fit). All three steps share the shape, so they grow together
        # and no card is left with dead space at the bottom.
        import re
        import build
        home = dict((p, b) for p, t, d, k, b in build.PAGES)["/"]
        steps = re.findall(
            r'<div class="flow-step[^"]*">(.*?)</div>', home, re.S)
        self.assertEqual(len(steps), 3)
        for body in steps:
            # Title (<strong>, display:block), value line and note
            # line are separate lines; measure each, not the
            # concatenation.
            m = re.match(
                r'<span[^>]*>\d</span><strong>([^<]*)</strong>'
                r'([^<]*)<span class="flow-note">([^<]*)</span>$',
                body.strip(), re.S)
            self.assertIsNotNone(m, "flow step shape changed: %r" % body)
            title, value, note = m.group(1), m.group(2), m.group(3)
            self.assertLessEqual(len(title), 21,
                                 "flow step title wraps: %r" % title)
            self.assertLessEqual(len(value), 26,
                                 "flow step value wraps: %r" % value)
            self.assertLessEqual(len(note), 40,
                                 "flow step note wraps: %r" % note)
        self.assertIn(
            "<strong>Victim loses</strong>0.909091 USDC"
            '<span class="flow-note">of a 100,000 USDC deposit</span></div>',
            home)
        self.assertNotIn("0.909091 USDC of a 100,000 USDC deposit</div>", home)
        # The full sentence survives just above the flow and in the
        # aria-label, so nothing was lost by shortening the step body.
        self.assertIn("loses <strong>0.909091 USDC</strong> of a 100,000 USDC",
                      home)
        self.assertIn("the victim's 100,000 USDC deposit loses 0.909091 USDC",
                      home)

    def test_home_cards_bodies_are_balanced(self):
        # Visual verdict #57 remainder: the Free tool card's body was
        # ~2 lines while Paid service and Research were ~4, so the
        # bottom links sat at different heights. Fix: the Free tool
        # body used to name the six checks (same list as the /checker/
        # page description) to reach the same length band; since
        # visual verdict #146 (2026-11-21) the names live only in the
        # hero aside, which already lists them, and the card lead says
        # what the checks do instead. Still matters after verdict #112
        # item 2 removed the margin-top:auto pinning: unpinned links
        # follow their body text, so balanced bodies keep the three
        # links at near-equal heights instead of drifting apart.
        # Visual verdict #145 (2026-11-21): the cards were single
        # dense paragraphs, so each card is now a lead paragraph plus
        # a short bullet list. The body is measured across the whole
        # card (lead + bullets, bottom link excluded) — the first
        # paragraph alone no longer holds the body.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        home = dict((p, b) for p, t, d, k, b in build.PAGES)["/"]
        cards = re.findall(
            r'<section class="card"><h2>([^<]*)</h2>(.*?)<p class="card-link">',
            home, re.S)
        self.assertEqual(len(cards), 3)
        bodies = {}
        for title, body in cards:
            self.assertIn("<ul>", body, "%s card has no bullet list" % title)
            self.assertGreaterEqual(body.count("<li>"), 2,
                                    "%s card has fewer than 2 bullets" % title)
            text = re.sub(r"<[^>]+>", "", body)
            bodies[title] = len(text)
        # The six check names are listed once, in the hero aside —
        # not repeated in the Free tool card (verdict #146 dedup).
        # The comma-joined list still lives in the /checker/ page
        # description, which is a different page, not the homepage.
        self.assertNotIn("rounding, donation inflation, preview consistency, "
                         "fee conservation, share-price sanity, minimum viable "
                         "deposit", home)
        for name in ("Rounding", "Donation inflation", "Preview consistency",
                     "Fee conservation", "Share-price sanity",
                     "Minimum viable deposit"):
            self.assertIn("<li>%s</li>" % name, home,
                          "hero aside no longer lists %s" % name)
        self.assertIn("the donation check shows exactly what a donation does "
                      "to the next depositor", home)
        for title, n in bodies.items():
            self.assertGreaterEqual(n, 180, "%s body too short: %d" % (title, n))
        self.assertLessEqual(max(bodies.values()) / min(bodies.values()), 1.4,
                             "card bodies unbalanced: %r" % bodies)

