    def test_donation_deposit_hook_reentrancy_guide_numbers(self):
        # Pins /guides/erc4626-donation-deposit-hook-reentrancy/ to
        # its model (offset 0): seed 1 base unit / 1 share-base-unit
        # at $1.00; Mallory has 100,000 USDC to deposit plus
        # 1,000,000 USDC to donate; Alice has 100,000 USDC.
        import importlib.util
        from pathlib import Path
        model_path = (Path.home() / "workspace/taskmarket/site"
                      / "donation-deposit-hook-reentrancy-model.py")
        spec = importlib.util.spec_from_file_location(
            "donation_deposit_hook_reentrancy_model", model_path)
        model = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(model)
        USDC = model.USDC

        # 1. Control, donation only: Alice mints 0 shares, Mallory
        # redeems the seed for 1,100,000.000001, profit 100,000.000001.
        _, vault = model.fresh()
        vault.donate("mallory", 1_000_000 * USDC)
        self.assertEqual(vault.deposit("alice", 100_000 * USDC, "alice"),
                         0)
        out = vault.redeem("mallory", 1)
        self.assertEqual(out, 1_100_000 * USDC + 1)
        self.assertEqual(out - 1_000_000 * USDC - 1, 100_000 * USDC)

        # 2. Donation first, hook deposit: hook mint 0, deposit 0,
        # Mallory still holds only the seed; redeem 1,200,000.000001,
        # profit identical to the control.
        _, vault = model.fresh(hook_mode="auto-credit")
        vault.donate("mallory", 1_000_000 * USDC)
        self.assertEqual(
            vault.deposit("mallory", 100_000 * USDC, "mallory"), 0)
        self.assertEqual(vault.shares["mallory"], 1)
        self.assertEqual(vault.deposit("alice", 100_000 * USDC, "alice"),
                         0)
        out = vault.redeem("mallory", 1)
        self.assertEqual(out, 1_200_000 * USDC + 1)
        self.assertEqual(out - 1_100_000 * USDC - 1, 100_000 * USDC)

        # 3. Hook first: Mallory holds 200,001 shares; Alice's
        # double mint is 36,363.636362 shares; Mallory redeems
        # 1,015,384.615393, profit -84,615.384607; Alice's shares are
        # worth 184,615.384608; the ledger closes exactly.
        _, vault = model.fresh(hook_mode="auto-credit")
        vault.deposit("mallory", 100_000 * USDC, "mallory")
        self.assertEqual(vault.shares["mallory"], 200_000 * USDC + 1)
        vault.donate("mallory", 1_000_000 * USDC)
        vault.deposit("alice", 100_000 * USDC, "alice")
        self.assertEqual(vault.shares["alice"], 36_363_636_362)
        self.assertEqual(vault.total_supply, 236_363_636_363)
        out = vault.redeem("mallory", vault.shares["mallory"])
        self.assertEqual(out, 1_015_384_615_393)
        self.assertEqual(out - 1_100_000 * USDC, -84_615_384_607)
        self.assertEqual(vault.share_value("alice"), 184_615_384_608)
        self.assertEqual(out + vault.share_value("alice"),
                         1_200_000 * USDC + 1)

        # 4. Victim-side hook: Alice's hook mint 0, deposit 0;
        # Mallory redeems the seed for 1,100,000.000001, as control.
        _, vault = model.fresh(hook_mode="auto-credit")
        vault.donate("mallory", 1_000_000 * USDC)
        self.assertEqual(vault.deposit("alice", 100_000 * USDC, "alice"),
                         0)
        self.assertEqual(vault.shares["alice"], 0)
        out = vault.redeem("mallory", 1)
        self.assertEqual(out, 1_100_000 * USDC + 1)

        # 5. No-op defense: single mint (0 at the inflated price);
        # Alice also deposits 0; Mallory redeems 1,200,000.000001.
        _, vault = model.fresh(hook_mode="noop")
        vault.donate("mallory", 1_000_000 * USDC)
        self.assertEqual(
            vault.deposit("mallory", 100_000 * USDC, "mallory"), 0)
        self.assertEqual(vault.shares["mallory"], 1)
        self.assertEqual(vault.deposit("alice", 100_000 * USDC, "alice"),
                         0)
        out = vault.redeem("mallory", 1)
        self.assertEqual(out, 1_200_000 * USDC + 1)

        # No duplicate add() for this guide in build.py.
        build = (Path.home() / "workspace/taskmarket/site/build.py"
                 ).read_text()
        self.assertEqual(
            build.count('add("/guides/erc4626-donation-deposit-hook-reentrancy/"'),
            1)
    def test_donation_rebase_collateral_guide_numbers(self):
        # Pins the donation x rebase-collateral model: a 1,000,000
        # USDC / 1,000,000 share vault, price $1.00, Alice holding
        # 100,000 shares (10%), CF 80%. Importing the model re-runs
        # its assertions; the checks below independently re-derive
        # the headline numbers. The build.py guide
        # /guides/erc4626-donation-rebase-collateral/ exists since
        # 2026-11-17, so its add() count is asserted below.
        import importlib.util
        from fractions import Fraction
        from pathlib import Path
        model_path = (Path.home() / "workspace/taskmarket/site"
                      / "donation-rebase-collateral-model.py")
        spec = importlib.util.spec_from_file_location(
            "donation_rebase_collateral_model", model_path)
        model = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(model)

        USDC = 1_000_000
        # Case 1: 1,000,000 USDC donation on a 1 bu seed doubles
        # the price to 2000000000001/1000000000001; oracle follows,
        # so Alice's max borrow is 159,999,999,999 bu
        # ($159,999.999999) at ~80% LTV.
        p2 = Fraction(2_000_000_000_001, 1_000_000_000_001)
        self.assertEqual(Fraction(1_000_000 * USDC + 1 + 1_000_000 * USDC,
                                  1_000_000 * USDC + 1), p2)
        cap = (100_000 * USDC * p2 * Fraction(4, 5))
        self.assertEqual(cap.numerator // cap.denominator,
                         159_999_999_999)
        # Case 2: the other 90% redeem at the inflated price and
        # take $1,799,999.999999 out -- but the price fraction is
        # unchanged, so Alice's collateral and LTV do not move.
        out_others = 900_000 * USDC * p2
        self.assertEqual(out_others.numerator // out_others.denominator,
                         1_799_999_999_999)
        a3 = Fraction(2_000_000_000_001, 1) - out_others
        self.assertEqual(a3 / (1_000_000 * USDC + 1 - 900_000 * USDC),
                         p2)
        # Case 3: the attacker's 1 seed share redeems for a hair
        # under 2 base units ($0.000002) on a $1,000,000.000001
        # outlay (1 base unit seed + 1,000,000 USDC donation).
        # The old pin said "2 base units" and "$1,000,001.000001":
        # both were wrong -- the exact redemption is
        # 2000000000001/1000000000001 base units (a hair under 2,
        # and a real redeem floors to 1), and the outlay is one
        # dollar less than the guide used to say.
        self.assertEqual(1 * p2, Fraction(2_000_000_000_001,
                                          1_000_000_000_001))
        self.assertLess(1 * p2, 2)  # a hair under 2 base units
        self.assertEqual((1 * p2).numerator // (1 * p2).denominator,
                         1)  # a real redeem floors to 1 base unit
        outlay = 1 + 1_000_000 * USDC
        self.assertEqual(outlay, 1_000_000_000_001)  # $1,000,000.000001
        # Net: outlay minus the hair-under-2 redemption, exact.
        self.assertEqual(Fraction(outlay, 1) - 1 * p2,
                         Fraction(1_000_000_000_000_000_000_000_000,
                                  1_000_000_000_001))
        # Case 4: contrast -- a -20% rebase at the stale $1.00
        # oracle puts the same $80,000 loan at exactly 100% LTV.
        self.assertEqual(100_000 * USDC * Fraction(4, 5), 80_000 * USDC)
        self.assertEqual(Fraction(80_000 * USDC, 1)
                         / (100_000 * USDC * Fraction(4, 5)), 1)
        # No duplicate add() for this guide in build.py.
        build = (Path.home() / "workspace/taskmarket/site/build.py"
                 ).read_text()
        self.assertEqual(
            build.count('add("/guides/erc4626-donation-rebase-collateral/"'),
            1)
        self.assertEqual(
            build.count('/guides/erc4626-donation-rebase-collateral/'),
            3)  # add() + guides-index <li> + cross-link in the
        # donation-underlying-depeg guide (2026-11-17)
        # The guide text itself carries the corrected figures:
        # no "$1,000,001.000001" anywhere in build.py, the
        # redemption is a hair under 2 base units, and the
        # donation pays back two trillionths of itself.
        self.assertEqual(build.count("$1,000,001.000001"), 0)
        self.assertIn("a hair under 2 base units", build)
        self.assertIn("two trillionths of itself", build)
        # Pins the donation x underlying-depeg model: a 1,000,000
        # sUSDS / 1,000,000 share vault, unit price 1 sUSDS, peg
        # $1.00 -> $0.90, a 100,000 sUSDS donation, a 1% holder
        # with 10,000 shares. Importing the model re-runs its
        # assertions; the checks below independently re-derive the
        # headline numbers. The build.py guide
        # /guides/erc4626-donation-underlying-depeg/ exists since
        # 2026-11-17, so its add() count is asserted below.
        import importlib.util
        from fractions import Fraction
        from pathlib import Path
        model_path = (Path.home() / "workspace/taskmarket/site"
                      / "donation-underlying-depeg-model.py")
        spec = importlib.util.spec_from_file_location(
            "donation_underlying_depeg_model", model_path)
        model = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(model)

        SUSDS = 10**18
        balance = 1_000_000 * SUSDS
        shares = 1_000_000
        donation = 100_000 * SUSDS
        holder = 10_000
        peg = Fraction(1)
        depeg = Fraction(9, 10)

        def value_usd(bal, price):
            return Fraction(bal, SUSDS) * price

        # Case 1: donation after the depeg. The gift is worth
        # $90,000, not $100,000; vault $990,000; the 1% holder
        # gains exactly $900 (1% of the gift).
        self.assertEqual(value_usd(balance, depeg), 900_000)
        self.assertEqual(value_usd(donation, depeg), 90_000)
        self.assertEqual(value_usd(balance + donation, depeg), 990_000)
        self.assertEqual(Fraction(holder) * value_usd(balance, depeg)
                         / shares, 9_000)
        self.assertEqual(Fraction(holder)
                         * value_usd(balance + donation, depeg)
                         / shares, 9_900)
        # Case 2: donation before the depeg reaches the identical
        # endpoint -- $11,000 at $1.00, then $9,900 at $0.90.
        self.assertEqual(value_usd(balance + donation, peg), 1_100_000)
        self.assertEqual(Fraction(holder)
                         * value_usd(balance + donation, peg)
                         / shares, 11_000)
        self.assertEqual(Fraction(holder)
                         * value_usd(balance + donation, depeg)
                         / shares, 9_900)
        # Case 3: redeeming is exact -- 10,000 shares pay 11,000
        # sUSDS ($9,900), and a 1-share redemption is exactly
        # 1.1 sUSDS with no dust.
        self.assertEqual((holder * (balance + donation)) // shares,
                         11_000 * SUSDS)
        self.assertEqual(value_usd(11_000 * SUSDS, depeg), 9_900)
        self.assertEqual((1 * (balance + donation)) // shares,
                         Fraction(11, 10) * SUSDS)
        # No duplicate add() for this guide in build.py.
        build = (Path.home() / "workspace/taskmarket/site/build.py"
                 ).read_text()
        self.assertEqual(
            build.count('add("/guides/erc4626-donation-underlying-depeg/"'),
            1)
        self.assertEqual(
            build.count('/guides/erc4626-donation-underlying-depeg/'),
            2)  # add() + guides-index <li>

    def test_result_banner_names_the_failure(self):
        # Visual verdict #54 (2026-11-17): the "Result: SOME FAILED"
        # heading was a weak pastel strip — same size as a normal h2,
        # no icon, no fail count, no failing check named — easy to skim
        # past even though it is the page's most important signal. The
        # banner is now a saturated red bar with white text, a cross
        # mark, and the count plus the failing check names; the pass
        # banner mirrors it with a tick and "6 of 6 checks passed".
        # Both renderers (Python static + Worker JS) must agree: the
        # JS side is verified by the /tmp result-banner harness (node),
        # not by this suite.
        # Visual verdict #91 (2026-11-18): the &#10005; (U+2715) cross
        # rendered as a tofu box in the headless-Chromium font stack —
        # Dingbats glyphs are not in system-ui on this Linux install,
        # and &#10003; (U+2713) is the same block, so it carries the
        # same risk. Both marks are now inline SVG (currentColor,
        # font-independent); no Dingbats entity may remain in either
        # renderer's banner.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        failed = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn('class="result-banner fail"', failed)
        self.assertIn("Result: SOME FAILED &mdash; "
                      "1 of 6 failed: Donation inflation", failed)
        self.assertIn('<svg class="banner-mark"', failed)
        self.assertIn('M3.5 3.5l9 9M12.5 3.5l-9 9', failed)
        self.assertNotIn("&#10005;", failed)
        passed = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertIn('class="result-banner pass"', passed)
        self.assertIn("Result: ALL PASS &mdash; "
                      "6 of 6 checks passed", passed)
        self.assertIn('<svg class="banner-mark"', passed)
        self.assertIn('M2.5 8.5 6.5 12.5 13.5 3.5', passed)
        self.assertNotIn("&#10003;", passed)
        # The fail banner is saturated red with white text, not the old
        # pale pink strip.
        src = (Path.home() / "workspace/taskmarket/site/build.py"
               ).read_text()
        self.assertIn('.result-banner.fail{background:#b91c1c;color:#fff',
                      src)
        self.assertNotIn('.result-banner.fail{background:#fdecea', src)
        # The SVG marks are sized by CSS, and the JS mirror carries the
        # identical markup (both path strings appear twice in build.py:
        # once in the Python constants, once in the JS renderer).
        self.assertIn('.result-banner .banner-mark{width:.9em', src)
        self.assertEqual(src.count('M2.5 8.5 6.5 12.5 13.5 3.5'), 2)
        self.assertEqual(src.count('M3.5 3.5l9 9M12.5 3.5l-9 9'), 2)
        self.assertNotIn('&#10003;', src)
        self.assertNotIn('&#10005;', src)

    def test_copy_link_button_rides_inside_banner(self):
        # Visual verdict #100 leftover (2026-11-18): "Copy link to
        # these results" sat in its own <p> between the banner and
        # the first card -- a stranded row; measured live at 1919px:
        # banner->card gap 95.3px, the row alone 48.7px + 22.1px
        # margins. The button now rides inside the banner h2
        # (flex item on desktop, full-width wrapped line on
        # <=640px), so the stranded row and its gap are gone; the
        # copy script still ships once, right after the banner.
        # Corrected 2026-11-20: the original float:right
        # implementation only *looked* inside the banner -- on the
        # FAIL banner the button dropped a line and hung 27px
        # below it, because a dropped float does not expand its
        # parent. Flex keeps it on the banner's own line.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        passed = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertIn('class="result-banner pass"', passed)
        self.assertIn('copy-link-btn', passed)
        # Button (and its status span) sit inside the banner h2,
        # before the closing tag; no stranded <p> row remains.
        self.assertLess(passed.index('copy-link-btn'),
                        passed.index('</h2>'))
        self.assertNotIn('<p><button', passed)
        self.assertEqual(passed.count('function copyResultsLink'), 1)
        self.assertEqual(passed.count('Copy link to these results'), 1)
        # Both renderers carry the button: Python markup + JS mirror.
        # 'Copy link to these results' appears 2x in build.py: the
        # COPY_LINK_HTML comment and the JS mirror (the Python markup
        # splits the phrase across two string literals, so it does
        # not match as one substring there).
        src = (Path.home() / "workspace/taskmarket/site/build.py"
               ).read_text()
        self.assertEqual(src.count('Copy link to these results'), 2)
        # 'copy-link-btn' appears 3x: CSS desktop rule + Python
        # markup + JS mirror. The mobile rule used to name it too
        # (4x); visual verdict #148 moved the full-width mobile
        # rule to the .banner-actions group, so it no longer does.
        self.assertEqual(src.count('copy-link-btn'), 3)
        self.assertIn('.result-banner .copy-link-btn{flex:none', src)
        self.assertIn('@media (max-width:640px){.result-banner{flex-wrap:wrap}'
                      '.result-banner .banner-actions{flex:1 1 100%', src)

    def test_banner_mark_rides_with_first_line(self):
        # Visual verdict #148 (2026-11-22): on the FAIL banner the
        # cross mark was a bare flex item of the h2, vertically
        # centred — at 1919px it sat 46.9px below line 0 (6.3px
        # below line 1), an orphaned x at the start of line 2, and
        # the copy button sat mid-banner; "Link copied." squeezed
        # to two lines (51.9px wide, 50.4px tall). At 360px the mark
        # wrapped onto its own line above the text (banner 410.6px
        # tall). The banner is now two flex groups: mark + text in
        # .banner-text (the mark is inline at the start of line 1),
        # button + status in .banner-actions (top-aligned, status
        # nowrap). Both renderers must carry the same structure.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        for kwargs in (dict(decimals_offset=0, min_deposit=0,
                            perf_fee_bps=0),
                       dict(decimals_offset=6, min_deposit=1_000_000,
                            perf_fee_bps=1000)):
            html = build.results_html(run_all(Vault(**kwargs)),
                                      vic=100_000_000_000, off=kwargs["decimals_offset"],
                                      mn=kwargs["min_deposit"], fee=kwargs["perf_fee_bps"])
            h2 = html.split("</h2>")[0]
            self.assertIn('<span class="banner-text">', h2)
            self.assertIn('<span class="banner-actions">', h2)
            # Mark is inside the text group, before the verdict text.
            text = h2.split('<span class="banner-text">')[1].split(
                '</span>')[0]
            self.assertIn('<svg class="banner-mark"', text)
            self.assertIn("Result:", text)
            self.assertLess(text.index('<svg class="banner-mark"'),
                            text.index("Result:"))
            # Text group precedes the actions group; button and
            # status sit inside the actions group, in that order.
            self.assertLess(h2.index('banner-text'),
                            h2.index('banner-actions'))
            actions = h2.split('<span class="banner-actions">')[1]
            self.assertIn('copy-link-btn', actions)
            self.assertIn('id="copylink-msg"', actions)
            self.assertLess(actions.index('copy-link-btn'),
                            actions.index('copylink-msg'))
        # CSS: top-aligned groups, status never wraps.
        self.assertIn(
            ".result-banner .banner-text{flex:1 1 auto;min-width:0}",
            build.CSS)
        self.assertIn(
            ".result-banner .banner-actions{flex:none;display:flex;"
            "align-items:center;gap:.5em",
            build.CSS)
        self.assertIn(
            ".result-banner #copylink-msg{font-size:.62em;"
            "font-weight:600;white-space:nowrap}",
            build.CSS)
        # JS mirror carries the identical two-group markup.
        src = (Path.home() / "workspace/taskmarket/site/build.py"
               ).read_text()
        self.assertIn(
            "<span class='banner-text'>\"+banner+\"</span>"
            "<span class='banner-actions'>",
            src)

    def test_guide_link_is_named_and_at_card_bottom(self):
        # Visual verdict #54 item c (2026-11-17): "Read the guide
        # &rarr;" appeared six times, word for word, between each
        # card's description and its result numbers — six identical
        # green links that interrupted the desc-to-numbers flow and
        # read as noise. The link now sits at the bottom of each
        # card, after the numbers, muted grey and small, and names
        # its check ("Guide: Donation inflation &rarr;") so the six
        # links are no longer identical. The JS renderer mirrors
        # this (verified by the /tmp node harness, not this suite).
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertNotIn("Read the guide", html)
        expected = [
            ("Rounding directions", "/guides/erc4626-rounding-errors/"),
            ("Donation inflation", "/guides/erc4626-donation-attack/"),
            ("Preview consistency", "/guides/erc4626-preview-consistency/"),
            ("Fee conservation", "/guides/erc4626-fee-conservation/"),
            ("Share-price sanity", "/guides/vault-share-price-manipulation/"),
            ("Minimum viable deposit", "/guides/erc4626-minimum-deposit/"),
        ]
        self.assertEqual(html.count("class='check-guide'"), 6)
        cards = html.split("<section class='check-card'>")[1:]
        self.assertEqual(len(cards), 6)
        # Card order follows run_all(), not CHECK_META — match by title.
        # Each chunk runs to the next card's opening tag, so cut it at
        # its own closing tag first (the last card has no next card —
        # its chunk runs on into the notice div).
        by_title = {}
        for card in cards:
            card = card.split("</section>", 1)[0]
            title = card.split("</span> ", 1)[1].split("</h3>", 1)[0]
            by_title[title] = card
        self.assertEqual(sorted(by_title),
                         sorted(title for title, _ in expected))
        for title, href in expected:
            card = by_title[title]
            self.assertIn(f"<p class='check-guide'><a href='{href}'>"
                          f"Guide: {title} &rarr;</a></p>", card)
            # The guide link is the card's last paragraph: it comes
            # after the description and after every result number.
            self.assertTrue(card.rstrip().endswith(
                f"<p class='check-guide'><a href='{href}'>"
                f"Guide: {title} &rarr;</a></p>"))
        src = (Path.home() / "workspace/taskmarket/site/build.py"
               ).read_text()
        self.assertIn(".check-guide{font-size:.85em;color:#6b7280", src)
        self.assertIn(".check-guide a{color:#6b7280", src)
        self.assertNotIn("Read the guide", src)

    def test_short_cards_state_their_pass_rule(self):
        # Visual verdict #104 item 1 (corrected): the short cards
        # carry one detail line against the donation card's table +
        # chart, so the page reads as one long card and four sparse
        # ones. Equal heights would manufacture real blank space
        # inside the cards (#103), so the short cards instead state
        # their pass rule — the exact criterion and the scenario it
        # was tested on, straight from the model. Donation already
        # has its pass-bound paragraph and minimum-viable-deposit
        # states its rule in its blurb, so those two carry no rule
        # line. The rule texts below are verified against the model
        # docstrings and the amounts the checks actually run:
        # rounding amounts (1, 100, 10,000 USDC) and the 1-base-unit
        # tolerance; preview 10,000 USDC deposit + 1,000,000-share
        # mint/redeem; fee 10,000 USDC yield; share-price two
        # 100,000 USDC deposits, 1-base-unit tolerance.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        expected = {
            "Rounding directions":
                "Every preview within 1 base unit of the exact ratio"
                " — deposits of 1, 100, 10,000 USDC.",
            "Preview consistency":
                "Preview must equal execution exactly — tested on a "
                "10,000 USDC deposit and a 1,000,000-share mint and redeem.",
            "Fee conservation":
                "Holder gain + fee must equal the 10,000 USDC yield "
                "exactly, and the fee must equal the yield times the "
                "fee rate.",
            "Share-price sanity":
                "Price per 1,000,000 shares must not fall by more than "
                "1 base unit after a second 100,000 USDC deposit.",
        }
        for v, kwargs in (
                (Vault(decimals_offset=6, min_deposit=1_000_000,
                       perf_fee_bps=1000), {}),
                (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                 {"off": 0, "mn": 0, "fee": 0})):
            html = build.results_html(run_all(v), **kwargs)
            self.assertEqual(html.count("<p class='check-rule'>"), 4)
            cards = html.split("<section class='check-card'>")[1:]
            by_title = {}
            for card in cards:
                card = card.split("</section>", 1)[0]
                title = card.split("</span> ", 1)[1].split("</h3>", 1)[0]
                by_title[title] = card
            for title, rule in expected.items():
                self.assertIn(
                    f"<p class='check-rule'><strong>Pass rule:</strong> "
                    f"{rule}</p>", by_title[title])
                # The rule sits after the numbers and before the guide
                # link, which stays the card's last paragraph.
                self.assertLess(
                    by_title[title].index("check-rule"),
                    by_title[title].index("check-guide"))
            for title in ("Donation inflation",
                          "Minimum viable deposit"):
                self.assertNotIn("check-rule", by_title[title])
        self.assertIn(".check-rule{font-size:.92em;color:#4b5563",
                      build.CSS)
        # The Worker-side template renders the same lines: the rule
        # is the fourth CHECK_META element, rendered after the
        # details block and before the guide link.
        js = build.checker_results_html_js()
        self.assertIn("if(m[3]) h+=\"<p class='check-rule'>", js)
        for rule in expected.values():
            self.assertIn(rule, js)

    def test_cli_seeded_vault_passes_where_new_vault_fails(self):
        # The hosted checker lets a user seed the vault state (assets +
        # shares already in it); the repo CLI could not, so a live 50M
        # USDC vault at offset 0 could not be reproduced from the repo.
        # Verified against the model: a new vault at offset 0 fails
        # the donation check (worst victim loss 0.909091 USDC); the
        # same vault seeded with 50M USDC at price 1.00 passes all
        # six (worst victim loss 0.000013 USDC).
        import io
        from contextlib import redirect_stdout
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import main as cli_main
        with redirect_stdout(io.StringIO()):
            self.assertEqual(cli_main(["--offset", "0"]), 1)
        out = io.StringIO()
        with redirect_stdout(out):
            rc = cli_main(["--offset", "0",
                           "--vault-assets-usdc", "50000000",
                           "--vault-shares", "50000000000000"])
        self.assertEqual(rc, 0)
        self.assertIn("ALL PASS", out.getvalue())

    def test_cli_vault_shares_parse_exact_large_integers(self):
        # Shares are raw integers and can exceed float precision (an
        # 18-decimal vault holds ~1e25 raw shares); the parser must
        # never round them through float. Commas and underscores are
        # accepted, as in the USDC parser.
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import _shares
        self.assertEqual(_shares("50,000,000,000,000"), 50_000_000_000_000)
        self.assertEqual(_shares("5_000"), 5000)
        self.assertEqual(_shares("50000000000000000000000000"), 5 * 10**25)
        with self.assertRaises(ValueError):
            _shares("1.5")

    def test_cli_half_filled_vault_state_is_refused_up_front(self):
        # Assets without shares (or vice versa) is not a vault — but
        # the two seeded checks used to disagree about it: the donation
        # check refused ("incomplete vault state") while the
        # minimum-viable-deposit check computed a verdict against the
        # impossible state (assets-only read as a donated-to empty
        # vault, shares-only as shares worth nothing — one input, two
        # answers, and the shares-only run even PASSED). The CLI now
        # refuses a half state up front (exit 2, usage error naming
        # both flags) before any check runs, so a forgotten flag can
        # never produce a mixed verdict.
        import io
        from contextlib import redirect_stdout, redirect_stderr
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import main as cli_main
        for argv in (["--offset", "0", "--vault-assets-usdc", "50000000"],
                     ["--offset", "0", "--vault-shares", "50000000000000"],
                     ["--offset", "0", "--vault-assets-usdc", "0",
                      "--vault-shares", "50000000000000"]):
            out, err = io.StringIO(), io.StringIO()
            with redirect_stdout(out), redirect_stderr(err):
                with self.assertRaises(SystemExit) as cm:
                    cli_main(argv)
            self.assertEqual(cm.exception.code, 2)
            self.assertIn("give both --vault-assets-usdc and --vault-shares",
                          err.getvalue())
            self.assertNotIn("[PASS]", out.getvalue())
            self.assertNotIn("[FAIL]", out.getvalue())

    def test_cli_negative_vault_state_is_rejected(self):
        # A negative asset or share count is not a vault either; the
        # CLI rejects it at parse time (exit 2) instead of reporting
        # a verdict about impossible state.
        import io
        from contextlib import redirect_stderr
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import main as cli_main
        with redirect_stderr(io.StringIO()):
            with self.assertRaises(SystemExit) as cm:
                cli_main(["--offset", "0", "--vault-assets-usdc", "-5"])
        self.assertEqual(cm.exception.code, 2)

    def test_cli_out_of_range_scalars_are_refused_up_front(self):
        # The hosted checker accepts offsets 0-30 and fees 0-10000
        # bps (its hint says 0-30, its inputs cap the fee, its
        # parseParams clamps both): outside those ranges the two
        # faces disagreed — offset -1 crashed the model with a
        # ValueError traceback (10**-1 is a float, _fmt_usdc needs
        # an int; the crash exited 1, indistinguishable from SOME
        # FAILED), offset 31 silently ran a vault the site cannot
        # express, a 200% fee PASSED fee conservation with a
        # negative holder gain, a negative fee paid the holder, a
        # negative minimum was silently ignored (the donation check
        # seeds max(min, 1 USDC), so the run returned the
        # 0-minimum vault's verdict), and a negative victim failed
        # every donation row as "below minimum deposit". The CLI
        # now refuses all four up front (exit 2, usage error
        # naming the range) before any check runs. Boundaries
        # still run: offset 0/30, fee 0/10000, min 0, and a zero
        # victim still runs (it fails honestly with "zero shares
        # minted" — a degenerate scenario, not a nonsense input).
        import io
        from contextlib import redirect_stdout, redirect_stderr
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import main as cli_main
        for argv, needle in (
                (["--offset", "-1"], "offset must be 0-30"),
                (["--offset", "31"], "offset must be 0-30"),
                (["--perf-fee-bps", "-5"],
                 "perf fee must be 0-10000 bps"),
                (["--perf-fee-bps", "20000"],
                 "perf fee must be 0-10000 bps"),
                (["--min-deposit-usdc", "-1"],
                 "minimum deposit must not be negative"),
                (["--victim-deposit-usdc", "-5"],
                 "victim deposit must not be negative")):
            out, err = io.StringIO(), io.StringIO()
            with redirect_stdout(out), redirect_stderr(err):
                with self.assertRaises(SystemExit) as cm:
                    cli_main(argv)
            self.assertEqual(cm.exception.code, 2)
            self.assertIn(needle, err.getvalue())
            self.assertNotIn("[PASS]", out.getvalue())
            self.assertNotIn("[FAIL]", out.getvalue())
        for argv, want_rc, want_out in (
                (["--offset", "0"], 1, "SOME FAILED"),
                (["--offset", "30"], 0, "ALL PASS"),
                (["--offset", "6", "--perf-fee-bps", "10000"], 0,
                 "ALL PASS"),
                (["--offset", "0", "--victim-deposit-usdc", "0"], 1,
                 "zero shares minted")):
            out, err = io.StringIO(), io.StringIO()
            with redirect_stdout(out), redirect_stderr(err):
                rc = cli_main(argv)
            self.assertEqual(rc, want_rc)
            self.assertIn(want_out, out.getvalue())

    def test_cli_mgmt_fee_flag_is_disclosed_as_unmodeled(self):
        # --mgmt-fee-bps-per-year is accepted (CLI, Action, README's
        # CI example) but none of the six checks reads it: the value
        # is stored on the Vault and never used, so a nonzero value
        # used to imply the fee had been checked — the same run with
        # 100 and with 0 printed byte-identical verdicts. The CLI now
        # says so on stderr whenever the value is nonzero, while the
        # verdict and the numbers stay identical to the same run with
        # 0; with 0 there is no note. The Action input description
        # and the README's honest limits carry the same disclosure.
        import io
        from contextlib import redirect_stdout, redirect_stderr
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import main as cli_main
